import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Locale;
import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println("===== STUDENT REPORT =====");
        System.out.println("Enter student name:");
        String studentName = reader.readLine();

        System.out.println("Enter marks for Subject 1:");
        String marks1Str = reader.readLine();
        BigDecimal marks1 = new BigDecimal(marks1Str);

        System.out.println("Enter marks for Subject 2:");
        String marks2Str = reader.readLine();
        BigDecimal marks2 = new BigDecimal(marks2Str);

        System.out.println("Enter marks for Subject 3:");
        String marks3Str = reader.readLine();
        BigDecimal marks3 = new BigDecimal(marks3Str);

        BigDecimal totalMarks = marks1.add(marks2).add(marks3);
        BigDecimal averageMarks = totalMarks.divide(new BigDecimal(3), 2, RoundingMode.HALF_UP);

        System.out.println();
        System.out.println("===== RESULT =====");
        System.out.println("Student: " + studentName);
        System.out.println("Total Marks: " + String.format(Locale.ROOT, "%04d", totalMarks.intValue()));
        System.out.println("Average: " + String.format(Locale.ROOT, "%.2f", averageMarks.abs()));

        if (averageMarks.compareTo(new BigDecimal(40)) >= 0) {
            System.out.println("Status: PASS");
        } else {
            System.out.println("Status: FAIL");
        }
    }
}
